// ============================================================
//  Perimenopause Self-Assessment — Score Calculator
//  Based on the Q004 blueprint symptom checklist.
//
//  Each of the 20 questions is YES / NO:
//    Yes = 1 point, No = 0 points. Max score = 20.
//
//  Scoring tiers — mirroring the Make.com blueprint switch:
//    score = 0        → Result 1 (No symptoms)
//    score 1–14       → Result 2 (Mild–Moderate symptoms)
//    score 15–20      → Result 3 (Significant symptoms)
// ============================================================

const data = $input.first().json.body || $input.first().json;

const fields = [
  'q1_water_retention',
  'q2_facial_hair',
  'q3_breast_tenderness',
  'q4_pain',
  'q5_vaginal_dryness',
  'q6_fatigue',
  'q7_concentration',
  'q8_urinary_incontinence',
  'q9_irritability',
  'q10_anxiety',
  'q11_mood_swings',
  'q12_depression',
  'q13_acne',
  'q14_low_libido',
  'q15_hot_flashes',
  'q16_sleep_disturbance',
  'q17_heart_disease_risk',
  'q18_osteoporosis_risk',
  'q19_weight_gain',
  'q20_irregular_periods'
];

let totalScore = 0;
const scores = {};
const warnings = [];

for (const field of fields) {
  const raw = data[field];
  const isYes = raw && String(raw).trim().toLowerCase() === 'yes';
  const score = isYes ? 1 : 0;
  scores[field] = { raw, score };
  totalScore += score;
  if (raw === undefined || raw === null || raw === '') {
    warnings.push(field + ' is missing');
  }
}

// Three-tier result — matching Q004 Make.com switch logic exactly
let resultNum, resultLabel, resultContent;
if (totalScore === 0) {
  resultNum = 1;
  resultLabel = 'No Symptoms Reported';
  resultContent = 'You have not reported any perimenopause symptoms at this time. This is reassuring, though symptoms can emerge gradually. Consider establishing a hormone baseline with a panel test so you have a reference point for the future.';
} else if (totalScore >= 1 && totalScore <= 14) {
  resultNum = 2;
  resultLabel = 'Mild to Moderate Symptoms';
  resultContent = 'You are experiencing some symptoms that may be linked to perimenopause. Fluctuating oestrogen and progesterone levels are the most likely cause. A hormone evaluation would help clarify whether hormone replacement therapy or other treatments could benefit you.';
} else {
  resultNum = 3;
  resultLabel = 'Significant Symptoms';
  resultContent = 'Your score indicates a high number of symptoms strongly associated with perimenopause. The wide range of symptoms you are experiencing — hot flashes, sleep disruption, mood changes, vaginal dryness, and more — are well-documented effects of declining oestrogen. We strongly recommend a comprehensive hormone panel and a consultation with one of our specialists.';
}

return [{ json: {
  patientName:    data.first_name   || '',
  patientEmail:   data.email        || '',
  mailingList:    data.mailing_list || '',
  totalScore,
  resultNum,
  resultLabel,
  resultContent,
  _debug_scores:   scores,
  _debug_warnings: warnings
}}];

const d = $input.first().json;
// Escape only the dynamic name used in the HTML greeting.
function escapePatientName(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const greeting = d.patientName ? ('Dear ' + escapePatientName(d.patientName)) : 'Hi there';
const year = new Date().getFullYear();

// Result-specific intro text
const introMap = {
  1: `Perimenopause is the transitional phase leading up to menopause, during which hormone levels — particularly oestrogen and progesterone — begin to fluctuate. Symptoms can begin up to 10 years before your last period, often in your late 30s or early 40s.<br/><br/>Based on your responses, you are not currently reporting symptoms associated with perimenopause. This is reassuring. However, establishing a hormone baseline now is a smart and proactive step — it gives you and your clinician a clear reference point for any future changes.<br/><br/>We recommend a female hormone panel as part of your routine health checks, alongside maintaining bone density, cardiovascular health, and hormonal wellness through regular exercise, a nutrient-rich diet, and good sleep hygiene.`,
  2: `Perimenopause is the transitional phase leading up to menopause, during which oestrogen and progesterone levels begin to fluctuate — sometimes dramatically. This can trigger a wide range of physical and emotional symptoms, many of which can be mistaken for stress, thyroid issues, or simply 'getting older'.<br/><br/>Based on your responses, you are experiencing a number of symptoms that may be linked to perimenopause. A hormone panel will help confirm whether fluctuating hormones are the cause, and your clinician can discuss a range of evidence-based options to relieve your symptoms — from bioidentical hormone replacement therapy (BHRT) to targeted supplements and lifestyle adjustments.<br/><br/>The sooner you act, the easier it is to manage your symptoms and protect your long-term bone and cardiovascular health.`,
  3: `Perimenopause is the transitional phase leading up to menopause, during which oestrogen and progesterone levels decline significantly. Your responses indicate a high number of symptoms that are strongly associated with this hormonal transition.<br/><br/>The symptoms you are experiencing — which may include hot flashes, sleep disruption, mood disturbance, vaginal dryness, memory changes, and physical discomfort — are real, measurable, and highly treatable. You do not have to simply 'put up with' how you are feeling.<br/><br/>Bioidentical hormone replacement therapy (BHRT) is a well-researched, effective option that has helped millions of women reclaim their quality of life during perimenopause. We strongly encourage you to get a comprehensive hormone panel and speak with one of our specialists — who understand what you are going through and can tailor a treatment plan specifically for you.`
};

const introText = introMap[d.resultNum] || introMap[2];

// Lab tests — same for all tiers but tier 3 gets extra emphasis
const labTests = [
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/ZRTBloodSpotTestKit-9_1024x1024_2x_3025b07b-9b81-4d8f-85a4-2c9aff366530_1024x1024@2x.jpg?v=1571716034',
    title: 'Female Hormone Panel — At Home Test Kit',
    desc: 'Measures FSH, LH, oestradiol, and progesterone from a simple blood spot collected at home. Ideal for identifying perimenopause and monitoring BHRT.',
    price: '$179.00',
    url: 'https://store.hrt.org/products/female-hormone-panel-at-home-test-kit'
  },
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/ZRTLabBloodUrineMultiTestKit_1024x1024@2x.jpg?v=1571716011',
    title: 'Comprehensive Female Hormone Profile (Blood Spot)',
    desc: 'A full hormonal picture: oestradiol, progesterone, testosterone, DHEA-S, cortisol, and thyroid. Clinician-reviewed results included.',
    price: '$269.00',
    url: 'https://store.hrt.org/products/comprehensive-female-hormone-profile-blood-spot'
  },
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/Thyroid_Health_Essentials_1024x1024_upclose_1024x1024@2x.png?v=1579640010',
    title: 'Elite Female Hormone Panel (Blood Spot/Urine)',
    desc: 'Our most comprehensive perimenopause profile. Includes oestrogen metabolites, adrenal hormones, bone markers, and nutritional cofactors.',
    price: '$299.00',
    url: 'https://store.hrt.org/products/elite-female-hormone-panel'
  }
];

const products = [
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/2056x2056_product_photos_Micronized_DHEA_transparent_1024x1024@2x.png?v=1571716034',
    title: 'DHEA (25mg) — Natural Hormone Support Supplement',
    desc: 'A precursor hormone that declines with age. Micronised DHEA supports oestrogen and testosterone production, energy levels, and healthy ageing in women.',
    url: 'https://store.hrt.org/products/dhea-25mg-natural-supplement-to-help-maintain-optimal-dhea-levels'
