    img: 'https://assets-global.website-files.com/632a33dda7f9eaa9ed6897ea/63555be813ceda6560a19756_Thyroid-Disease%E2%80%94The-Symptoms-Cures-and-Causes.jpeg',
    title: 'Hormone Replacement Therapy — What to Expect',
    url: 'https://www.hrt.org/hormone-replacement-therapy/'
  },
  {
    img: 'https://assets-global.website-files.com/632a33dda7f9eaa9ed6897ea/63555b7f12c18d7342ac77ba_Thyroid-Cancer%E2%80%94Signs-Risk-Types-and-Treatments.jpg',
    title: 'Bioidentical HRT vs Synthetic HRT',
    url: 'https://www.hrt.org/bioidentical-hrt-vs-synthetic-hrt/'
